style.css:
@-moz-document domain("youtube.com") {
/* Targets the inner modern logo graphic wrapper and hides the default red text/graphic */
    ytd-logo #logo-icon,
    ytd-topbar-logo-renderer #logo {
        opacity: 0 !important;
    }

    /* Injects your Sailor Moon custom logo cleanly into the open container space */
    ytd-logo a.ytd-logo::after,
    ytd-topbar-logo-renderer a#logo::after {
        content: "" !important;
        position: absolute !important;
        left: 15px !important;
        top: 10px !important;
        width: 120px !important; 
        height: 35px !important;
        
        /* REPLACE THE URL BELOW WITH YOUR PNG IMAGE LINK */
        background-image: url("https://i.ibb.co/8n0pHWX0/c25def660ed9cbb4a5dc17a5e3540885.png") !important;
        
        background-size: contain !important;
        background-repeat: no-repeat !important;
        background-position: center left !important;
        z-index: 9999 !important;
    }
    
    /* Ensures the absolute positioning container anchor behaves correctly */
    ytd-logo a.ytd-logo,
    ytd-topbar-logo-renderer a#logo {
        position: relative !important;
    }
}
